package dispatch

import "context"

type Mode int

const (
	ModeServer Mode = iota
	ModeLocal
)

// Options holds all parsed CLI inputs.
type Options struct {
	Mode                  Mode
	RepoPaths             []string
	Org                   string
	Since                 string
	Until                 string
	Branches              []string
	AllBranches           bool
	ImplicitCurrentBranch bool
	Generate              bool
	Voice                 string
}

// Run is the entry point after flags are parsed.
func Run(ctx context.Context, opts Options) (*Dispatch, error) {
	if opts.Mode == ModeServer {
		return runServer(ctx, opts)
	}
	return runLocal(ctx, opts)
}

package dispatch

import (
	"errors"
	"time"
)

var errDispatchMissingMarkdown = errors.New("dispatch generation returned no markdown")

// Dispatch is the rendered, in-memory representation returned from either server or local mode.
type Dispatch struct {
	Window        Window
	CoveredRepos  []string
	Repos         []RepoGroup
	Totals        Totals
	Warnings      Warnings
	GeneratedText string

	RequestedGenerate bool
	Generated         bool
}

type Window struct {
	NormalizedSince   time.Time
	NormalizedUntil   time.Time
	FirstCheckpointAt time.Time
	LastCheckpointAt  time.Time
}

type RepoGroup struct {
	FullName string
	Sections []Section
}

type Section struct {
	Label   string
	Bullets []Bullet
}

type Bullet struct {
	CheckpointID string
	Text         string
	Source       string
	Branch       string
	CreatedAt    time.Time
	Labels       []string
}

type Totals struct {
	Checkpoints         int
	UsedCheckpointCount int
	Branches            int
	FilesTouched        int
}

type Warnings struct {
	AccessDeniedCount  int
	PendingCount       int
	FailedCount        int
	UnknownCount       int
	UncategorizedCount int
}

// Package jsonutil provides JSON utilities with consistent formatting.
package jsonutil

import (
	"bytes"
	"encoding/json"
	"fmt"
)

// MarshalIndentWithNewline is like json.MarshalIndent but adds a trailing newline.
// This ensures JSON files have proper POSIX line endings.
func MarshalIndentWithNewline(v any, prefix, indent string) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent(prefix, indent)
	if err := enc.Encode(v); err != nil {
		return nil, fmt.Errorf("encoding JSON: %w", err)
	}
	return buf.Bytes(), nil
}

// MarshalWithNoHTMLEscape is like json.Marshal but disables HTML escaping.
func MarshalWithNoHTMLEscape(v any) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return nil, fmt.Errorf("encoding JSON: %w", err)
	}
	out := buf.Bytes()
	if len(out) > 0 && out[len(out)-1] == '\n' {
		out = out[:len(out)-1]
	}
	return out, nil
}

