271	func renderStringFlag(name string, value string) string {
272		if value == "" {
273			return ""
274		}
275		return name + " " + quoteShellValue(value)
276	}
277	
278	func quoteShellValue(value string) string {
279		if value == "" {
280			return `""`
281		}
282		if strings.ContainsAny(value, " ,:\t") {
283			return fmt.Sprintf("%q", value)
284		}
285		return value
286	}
