288	func runDispatchWizard(cmd *cobra.Command) (dispatchpkg.Options, error) {
289		choices, err := discoverDispatchWizardChoices(cmd.Context())
290		if err != nil {
291			return dispatchpkg.Options{}, err
292		}
293	
294		state := newDispatchWizardState()
295		if len(choices.repoOptions) > 0 {
296			state.selectedRepos = []string{choices.repoOptions[0].Value}
297		}
298		if len(choices.orgOptions) > 0 {
299			state.selectedOrg = choices.orgOptions[0].Value
300		}
301	
302		currentBranch := func() (string, error) {
303			return GetCurrentBranch(cmd.Context())
304		}
305		if branch, branchErr := currentBranch(); branchErr == nil {
306			state.applyCurrentBranchDefault(branch)
307		}
308	
309		form := NewAccessibleForm(
310			huh.NewGroup(
311				huh.NewSelect[string]().
312					Title("Dispatch mode").
313					Options(
314						huh.NewOption("Local", dispatchWizardModeLocal),
315						huh.NewOption("Cloud", dispatchWizardModeServer),
316					).
317					Value(&state.modeChoice),
318			).Title("Mode").Description("Choose where the dispatch should run."),
319			huh.NewGroup(
320				huh.NewSelect[string]().
321					Title("Scope").
322					OptionsFunc(func() []huh.Option[string] {
323						return choices.scopeOptions(state)
324					}, &state).
325					Value(&state.scopeType),
326			).Title("Scope").Description("Choose which cloud scope to dispatch.").
327				WithHideFunc(func() bool {
328					return !state.showScopePicker(choices)
329				}),
330			huh.NewGroup(
331				huh.NewMultiSelect[string]().
332					Title("Repos").
333					Description("Select repos to include.").
334					Filterable(true).
335					OptionsFunc(func() []huh.Option[string] {
336						return append([]huh.Option[string](nil), choices.repoOptions...)
337					}, nil).
338					Value(&state.selectedRepos).
339					Validate(func(value []string) error {
340						if state.effectiveScopeType(choices) == dispatchWizardScopeSelectedRepos && len(value) == 0 {
341							return errors.New("select at least one repo")
342						}
343						return nil
344					}),
345			).Title("Repos").Description("Choose which repos to include.").
346				WithHideFunc(func() bool {
347					return !state.showRepoPicker(choices)
348				}),
349			huh.NewGroup(
350				huh.NewSelect[string]().
351					Title("Organization").
352					Description("Select the organization to dispatch.").
353					OptionsFunc(func() []huh.Option[string] {
354						if len(choices.orgOptions) == 0 {
355							return []huh.Option[string]{huh.NewOption("No organizations discovered", "")}
356						}
357						return append([]huh.Option[string](nil), choices.orgOptions...)
358					}, nil).
359					Value(&state.selectedOrg).
360					Validate(func(value string) error {
361						if state.effectiveScopeType(choices) == dispatchWizardScopeOrganization && strings.TrimSpace(value) == "" {
362							return errors.New("select an organization")
363						}
364						return nil
365					}),
366			).Title("Organization").Description("Choose which organization to include.").
367				WithHideFunc(func() bool {
368					return !state.showOrganizationPicker(choices)
369				}),
370			huh.NewGroup(
371				huh.NewSelect[string]().
372					Title("Time window").
373					Options(
374						huh.NewOption("1 day", "1d"),
375						huh.NewOption("7 days", "7d"),
376						huh.NewOption("14 days", "14d"),
377						huh.NewOption("30 days", "30d"),
378					).
379					Value(&state.timeWindowPreset),
380			).Title("Window").Description("Choose the time window."),
381			huh.NewGroup(
382				huh.NewSelect[string]().
383					Title("Branch mode").
384					OptionsFunc(func() []huh.Option[string] {
385						return choices.branchModeOptions(state)
386					}, &state).
387					Value(&state.branchMode),
388			).Title("Branch mode").Description("Choose how dispatch should interpret branch scope.").
389				WithHideFunc(func() bool {
390					return !state.showBranchModePicker()
391				}),
392			huh.NewGroup(
393				huh.NewSelect[string]().
394					Title("Voice").
395					Options(
396						huh.NewOption("Neutral", "neutral"),
397						huh.NewOption("Marvin", "marvin"),
398						huh.NewOption("Custom", "custom"),
399					).
400					Value(&state.voicePreset),
401			).Title("Output").Description("Choose a preset voice."),
402			huh.NewGroup(
403				huh.NewInput().
404					Title("Custom voice").
405					Placeholder("Dry, skeptical release note narrator").
406					Value(&state.voiceCustom).
407					Validate(func(value string) error {
408						if state.showCustomVoiceInput() && strings.TrimSpace(value) == "" {
409							return errors.New("enter a custom voice")
410						}
411						return nil
412					}),
413			).Title("Custom voice").Description("Describe the dispatch voice.").
414				WithHideFunc(func() bool {
415					return !state.showCustomVoiceInput()
416				}),
417			huh.NewGroup(
418				huh.NewNote().
419					Title("Resolved options").
420					DescriptionFunc(func() string {
421						opts, resolveErr := state.resolve(choices, currentBranch)
422						if resolveErr != nil {
423							return "Validation error: " + resolveErr.Error()
424						}
425						return buildDispatchWizardSummary(opts)
426					}, &state),
427				huh.NewNote().
428					Title("Command").
429					DescriptionFunc(func() string {
430						opts, resolveErr := state.resolve(choices, currentBranch)
431						if resolveErr != nil {
432							return "Validation error: " + resolveErr.Error()
433						}
434						return buildDispatchCommand(opts)
435					}, &state),
436				huh.NewConfirm().
437					Title("Run dispatch?").
438					Affirmative("Run").
439					Negative("Cancel").
440					Value(&state.confirmRun),
441			).Title("Confirm").Description("Review the resolved command and run it."),
442		)
443	
444		if err := form.Run(); err != nil {
445			if handled := handleFormCancellation(cmd.OutOrStdout(), "dispatch", err); handled == nil {
446				return dispatchpkg.Options{}, errDispatchCancelled
447			}
448			return dispatchpkg.Options{}, err
449		}
450		if !state.confirmRun {
451			fmt.Fprintln(cmd.OutOrStdout(), "dispatch cancelled.")
452			return dispatchpkg.Options{}, errDispatchCancelled
453		}
454	
455		return state.resolve(choices, currentBranch)
456	}
