458	func discoverDispatchWizardChoices(ctx context.Context) (dispatchWizardChoices, error) {
459		currentRepo, err := paths.WorktreeRoot(ctx)
460		if err != nil {
461			return dispatchWizardChoices{}, fmt.Errorf("not in a git repository: %w", err)
462		}
463	
464		repoSlugs, err := listDispatchWizardRepos(ctx)
465		if err != nil || len(repoSlugs) == 0 {
466			repoSlugs = discoverLocalRepoSlugs(ctx, currentRepo)
467		}
468		sort.Strings(repoSlugs)
469	
470		repoOptions := make([]huh.Option[string], 0, len(repoSlugs))
471		seenRepoSlugs := make(map[string]struct{}, len(repoSlugs))
472		for _, repoSlug := range repoSlugs {
473			if repoSlug == "" {
474				continue
475			}
476			if _, ok := seenRepoSlugs[repoSlug]; ok {
477				continue
478			}
479			seenRepoSlugs[repoSlug] = struct{}{}
480			repoOptions = append(repoOptions, huh.NewOption(repoSlug, repoSlug))
481		}
482	
483		orgNames, err := listDispatchWizardOrgs(ctx)
484		if err != nil {
485			orgNames = nil
486		}
487		sort.Strings(orgNames)
488	
489		orgOptions := make([]huh.Option[string], 0, len(orgNames))
490		for _, org := range orgNames {
491			orgOptions = append(orgOptions, huh.NewOption(org, org))
492		}
493	
494		return dispatchWizardChoices{
495			currentRepo: currentRepo,
496			repoOptions: repoOptions,
497			orgOptions:  orgOptions,
498		}, nil
499	}
500	
501	func discoverLocalRepoRoots(ctx context.Context, currentRepo string) []string {
502		rootSet := map[string]struct{}{currentRepo: {}}
503		parent := filepath.Dir(currentRepo)
504	
505		entries, err := os.ReadDir(parent)
506		if err == nil {
507			for _, entry := range entries {
508				if !entry.IsDir() {
509					continue
510				}
511				candidate := filepath.Join(parent, entry.Name())
512				repoRoot, resolveErr := resolveGitTopLevel(ctx, candidate)
513				if resolveErr != nil {
514					continue
515				}
516				rootSet[repoRoot] = struct{}{}
517			}
518		}
519	
520		repoRoots := make([]string, 0, len(rootSet))
521		for repoRoot := range rootSet {
522			repoRoots = append(repoRoots, repoRoot)
523		}
524		sort.Slice(repoRoots, func(i, j int) bool {
525			if repoRoots[i] == currentRepo {
526				return true
527			}
528			if repoRoots[j] == currentRepo {
529				return false
530			}
531			return filepath.Base(repoRoots[i]) < filepath.Base(repoRoots[j])
532		})
533		return repoRoots
534	}
535	
536	func discoverLocalRepoSlugs(ctx context.Context, currentRepo string) []string {
537		repoRoots := discoverLocalRepoRoots(ctx, currentRepo)
538		repoSlugs := make([]string, 0, len(repoRoots))
539		seenRepoSlugs := make(map[string]struct{}, len(repoRoots))
540		for _, repoRoot := range repoRoots {
541			repoSlug := discoverRepoSlug(repoRoot)
542			if repoSlug == "" {
543				continue
544			}
545			if _, ok := seenRepoSlugs[repoSlug]; ok {
546				continue
547			}
548			seenRepoSlugs[repoSlug] = struct{}{}
549			repoSlugs = append(repoSlugs, repoSlug)
550		}
551		return repoSlugs
552	}
553	
554	func resolveGitTopLevel(ctx context.Context, path string) (string, error) {
555		cmd := exec.CommandContext(ctx, "git", "-C", path, "rev-parse", "--show-toplevel")
556		output, err := cmd.Output()
557		if err != nil {
558			return "", err
559		}
560		return strings.TrimSpace(string(output)), nil
561	}
562	
563	func discoverBranchOptions(ctx context.Context, repoRoot string) []huh.Option[string] {
564		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "for-each-ref", "--format=%(refname:short)", "refs/heads")
565		output, err := cmd.Output()
566		if err != nil {
567			return nil
568		}
569	
570		lines := strings.Split(strings.TrimSpace(string(output)), "\n")
571		branches := make([]string, 0, len(lines))
572		for _, line := range lines {
573			line = strings.TrimSpace(line)
574			if line != "" && !shouldHideDispatchWizardBranch(line) {
575				branches = append(branches, line)
576			}
577		}
578		sort.Strings(branches)
579	
580		options := make([]huh.Option[string], 0, len(branches))
581		for _, branch := range branches {
582			options = append(options, huh.NewOption(branch, branch))
583		}
584		return options
585	}
586	
587	func shouldHideDispatchWizardBranch(branch string) bool {
588		branch = strings.TrimSpace(branch)
589		return strings.HasPrefix(branch, "entire/")
590	}
591	
592	func discoverAuthenticatedDispatchWizardOrgs(ctx context.Context) ([]string, error) {
593		cmd := exec.CommandContext(ctx, "gh", "api", "user/orgs", "--jq", ".[].login")
594		output, err := cmd.Output()
595		if err != nil {
596			return nil, err
597		}
598	
599		orgs := make([]string, 0)
600		for _, line := range strings.Split(string(output), "\n") {
601			line = strings.TrimSpace(line)
602			if line != "" {
603				orgs = append(orgs, line)
604			}
605		}
606		sort.Strings(orgs)
607		return orgs, nil
608	}
609	
610	func discoverAuthenticatedDispatchWizardRepos(ctx context.Context) ([]string, error) {
611		cmd := exec.CommandContext(
612			ctx,
613			"gh",
614			"api",
615			"--paginate",
616			"user/repos?per_page=100&affiliation=owner,collaborator,organization_member&sort=full_name",
617			"--jq",
618			".[].full_name",
619		)
620		output, err := cmd.Output()
621		if err != nil {
622			return nil, err
623		}
624	
625		repos := make([]string, 0)
626		seen := make(map[string]struct{})
627		for _, line := range strings.Split(string(output), "\n") {
628			line = strings.TrimSpace(line)
629			if line == "" {
630				continue
631			}
632			if _, ok := seen[line]; ok {
633				continue
634			}
635			seen[line] = struct{}{}
636			repos = append(repos, line)
637		}
638		sort.Strings(repos)
639		return repos, nil
640	}
641	
642	func discoverRepoSlug(repoRoot string) string {
643		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
644		if err != nil {
645			return ""
646		}
647		remote, err := repo.Remote("origin")
648		if err != nil || len(remote.Config().URLs) == 0 {
649			return ""
650		}
651		owner, repoName, err := searchpkg.ParseGitHubRemote(remote.Config().URLs[0])
652		if err != nil {
653			return ""
654		}
655		return owner + "/" + repoName
656	}
