)

var errDispatchMissingMarkdown = errors.New("dispatch generation returned no markdown")

// Dispatch is the rendered, in-memory representation returned from either server or local mode.
type Dispatch struct {
	Window        Window
	CoveredRepos  []string
	Repos         []RepoGroup
	Totals        Totals
	Warnings      Warnings
	GeneratedText string

	RequestedGenerate bool
	Generated         bool
}

type Window struct {
	NormalizedSince   time.Time
	NormalizedUntil   time.Time
	FirstCheckpointAt time.Time
	LastCheckpointAt  time.Time
}

type RepoGroup struct {
	FullName string
	Sections []Section
}

type Section struct {
	Label   string
	Bullets []Bullet
}

type Bullet struct {
	CheckpointID string
	Text         string
	Source       string
	Branch       string
	CreatedAt    time.Time
	Labels       []string
}

type Totals struct {
	Checkpoints         int
	UsedCheckpointCount int
	Branches            int
	FilesTouched        int
}

type Warnings struct {
	AccessDeniedCount  int
	PendingCount       int
	FailedCount        int
	UnknownCount       int
	UncategorizedCount int
}

package dispatch

import (
	_ "embed"
	"strings"
)

//go:embed voices/neutral.md
var voiceNeutral string

//go:embed voices/marvin.md
var voiceMarvin string

// Voice is the resolved form of a --voice input.
type Voice struct {
	Name     string
	Text     string
	IsPreset bool
}

var presets = map[string]string{
	"neutral": voiceNeutral,
	"marvin":  voiceMarvin,
}

// ResolveVoice applies the resolution chain preset -> literal.
func ResolveVoice(value string) Voice {
	if value == "" {
		return Voice{Name: "neutral", Text: voiceNeutral, IsPreset: true}
	}

	name := strings.ToLower(strings.TrimSpace(value))
	if text, ok := presets[name]; ok {
		return Voice{Name: name, Text: text, IsPreset: true}
	}

	return Voice{Text: value}
}

// ListPresetNames returns the shipped preset names in stable order.
func ListPresetNames() []string {
	return []string{"neutral", "marvin"}
}

