219	func reachableCheckpointIDsOnHEAD(ctx context.Context, repoRoot string) (map[string]struct{}, error) {
220		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "HEAD", "--format=%B%x00")
221		output, err := cmd.Output()
222		if err != nil {
223			return nil, fmt.Errorf("list HEAD checkpoint trailers: %w", err)
224		}
225	
226		reachable := make(map[string]struct{})
227		for _, message := range strings.Split(string(output), "\x00") {
228			for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
229				reachable[checkpointID.String()] = struct{}{}
230			}
231		}
232		return reachable, nil
233	}
