236		remote, err := repo.Remote("origin")
237		if err != nil {
238			return "", fmt.Errorf("find origin remote: %w", err)
239		}
240		if len(remote.Config().URLs) == 0 {
241			return "", errors.New("origin remote has no URLs configured")
242		}
243	
244		owner, repoName, err := search.ParseGitHubRemote(remote.Config().URLs[0])
245		if err != nil {
246			return "", err
247		}
248		return owner + "/" + repoName, nil
249	}
