	}
	if got.Text != "/tmp/my-voice.md" {
		t.Fatalf("expected literal passthrough, got %q", got.Text)
	}
}

func TestResolveVoice_EmptyDefaultsToNeutral(t *testing.T) {
	t.Parallel()

