func (c *CloudClient) doJSON(ctx context.Context, method, path string, reqBody, out any) error {
	var body io.Reader
	if reqBody != nil {
		data, err := json.Marshal(reqBody)
		if err != nil {
			return fmt.Errorf("marshal request body: %w", err)
		}
		body = bytes.NewReader(data)
	}

	req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, body)
	if err != nil {
		return fmt.Errorf("create request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	if reqBody != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}

	resp, err := c.http.Do(req)
	if err != nil {
		return fmt.Errorf("%s %s: %w", method, path, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusUnauthorized {
		return errors.New("dispatch requires login — run `entire login`")
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20)) //nolint:errcheck // best-effort body read for error message
		trimmed := strings.TrimSpace(string(body))
		if trimmed == "" {
			return fmt.Errorf("%s %s: unexpected status %d", method, path, resp.StatusCode)
		}
		return fmt.Errorf("%s %s: unexpected status %d: %s", method, path, resp.StatusCode, trimmed)
	}
	if out == nil {
		return nil
	}
	if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
		return fmt.Errorf("decode response: %w", err)
	}
	return nil
}

export const requireAuth = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  return requireSessionAuth(c, next)
})

// Require Bearer token auth (for CLI/API clients using ent_ tokens)
export const requireBearerAuth = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  const authHeader = c.req.header("Authorization")

  if (!authHeader) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const parts = authHeader.split(" ")
  if (parts.length !== 2 || parts[0] !== "Bearer") {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const token = parts[1]
  if (!token.startsWith(API_TOKEN_PREFIX)) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const hash = await sha256Hex(token)
  const db = getDb(c.env)
  const lookup = await db.apiTokens.findByTokenHash(hash)

  if (!lookup) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  // Check expiration
  if (new Date(lookup.expires_at) < new Date()) {
    return c.json({ error: "Token expired" }, 401)
  }

  c.set("userId", lookup.user_id)
  c.set("tokenScope", lookup.scope)

  // Fire-and-forget: update last_used_at
  try {
    c.executionCtx.waitUntil(db.apiTokens.updateLastUsedAt(lookup.id))
  } catch {
    // executionCtx not available (e.g. in tests) — run inline
    void db.apiTokens.updateLastUsedAt(lookup.id)
  }

  await next()
})

// Require admin privileges (must be used after requireAuth)
export const requireAdmin = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  const userId = c.get("userId")
  const db = getDb(c.env)
  const user = await nullIfInvalidUuid(db.users.findById(userId))

  if (!user || !isAdmin(c.env, user.is_admin ?? false)) {
    return c.json({ error: "Forbidden" }, 403)
  }

  await next()
})

